from src.nodes.base import BaseNode
from src.runtime.assets.geometry import (
    get_geometry_analyzer, get_geometry_review, get_geometry_serializer,
    AssetMetrics,
)
import json

class Hou_Mcp_Geometry_Review(BaseNode):
    name = "hou_mcp_geometry_review"

    def __init__(self):
        super().__init__()
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("asset_json",   "string", widget_type="text", default="{}")
        self.add_input("metrics_json", "string", widget_type="text", default="")
        self.add_output("review_json",      "string")
        self.add_output("overall_score",    "float")
        self.add_output("grade",            "string")
        self.add_output("production_ready", "bool")
        self.add_output("findings_json",    "string")
        # [AUTO-GENERATED-PORTS-END]

    async def execute(self, inputs):
        asset_json   = str(inputs.get("asset_json",   "{}") or "{}")
        metrics_json = str(inputs.get("metrics_json", "")  or "")

        try:
            asset = json.loads(asset_json) if asset_json.strip() else {}
        except Exception as exc:
            self.log_error(f"Failed to parse asset_json: {exc}")
            return {"review_json": "{}", "overall_score": 0.0, "grade": "F", "production_ready": False, "findings_json": "[]", "exec_out": True}

        try:
            # If metrics_json supplied, use it directly; otherwise run full analysis
            if metrics_json.strip() and metrics_json.strip() != "{}":
                metrics_dict = json.loads(metrics_json)
                metrics = AssetMetrics.from_dict(metrics_dict)
            else:
                result  = get_geometry_analyzer().analyze_asset(asset)
                metrics = result.metrics
                if metrics is None:
                    raise ValueError("Geometry analysis returned no metrics")

            review_result = get_geometry_review().review(metrics)
            serializer    = get_geometry_serializer()

            self.log_info(
                f"Geometry review: {metrics.asset_id} grade={review_result.grade} "
                f"score={review_result.overall_score:.2f} "
                f"production_ready={review_result.production_ready}"
            )
            if not review_result.production_ready:
                for f in review_result.findings[:3]:
                    self.log_warning(f)

            return {
                "review_json":      serializer.serialize_review(review_result),
                "overall_score":    review_result.overall_score,
                "grade":            review_result.grade,
                "production_ready": review_result.production_ready,
                "findings_json":    json.dumps(review_result.findings, ensure_ascii=False),
                "exec_out":         True,
            }
        except Exception as exc:
            self.log_error(f"Geometry review failed: {exc}")
            return {"review_json": "{}", "overall_score": 0.0, "grade": "F", "production_ready": False, "findings_json": "[]", "exec_out": True}

def register_node():
    return Hou_Mcp_Geometry_Review
